/* Landing page — warm roastery palette scoped to .lp (palette opt-out from
 * `maude`; spacing, radii, fonts and easing still come from the DS tokens). */

.lp {
  --lp-paper: oklch(0.965 0.012 75);
  --lp-paper-2: oklch(0.925 0.02 70);
  --lp-ink: oklch(0.24 0.025 45);
  --lp-ink-2: oklch(0.42 0.03 50);
  --lp-ink-3: oklch(0.56 0.03 55);
  --lp-roast: oklch(0.32 0.05 40);
  --lp-roast-2: oklch(0.4 0.07 42);
  --lp-ember: oklch(0.62 0.15 45);
  --lp-ember-ink: oklch(0.47 0.13 42);
  --lp-line: oklch(0.85 0.02 65);

  background: var(--lp-paper);
  color: var(--lp-ink);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.55;
  width: 100%;
  min-height: 100%;
}
.lp * { box-sizing: border-box; }
.lp a { color: inherit; text-decoration: none; }
.lp h1, .lp h2, .lp h3 { font-family: var(--font-display); margin: 0; letter-spacing: -0.02em; }
.lp p { margin: 0; }

.lp-wrap { max-width: 1200px; margin: 0 auto; padding: 0 var(--space-7, 48px); }
.lp--m .lp-wrap { padding: 0 20px; }

.lp-eyebrow {
  font-family: var(--font-mono); font-size: 12px; letter-spacing: 0.12em;
  text-transform: uppercase; color: var(--lp-ember-ink);
}

/* Nav */
.lp-nav { display: flex; align-items: center; justify-content: space-between; height: 76px; }
.lp-logo { display: flex; align-items: center; gap: 10px; font-family: var(--font-display); font-weight: 700; font-size: 20px; }
.lp-logo-mark { width: 30px; height: 30px; border-radius: 50%; background: var(--lp-roast); position: relative; }
.lp-logo-mark::after {
  content: ""; position: absolute; left: 50%; top: 5px; bottom: 5px; width: 3px; margin-left: -1.5px;
  border-radius: 3px; background: var(--lp-paper); transform: rotate(18deg);
}
.lp-links { display: flex; gap: var(--space-6, 32px); font-size: 15px; color: var(--lp-ink-2); }
.lp-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  height: 48px; padding: 0 24px; border-radius: var(--radius-pill, 999px);
  font-weight: 600; font-size: 15px; border: 1px solid transparent; white-space: nowrap;
}
.lp-btn--primary { background: var(--lp-roast); color: var(--lp-paper); }
.lp-btn--ghost { border-color: var(--lp-ink); color: var(--lp-ink); }
.lp-btn--sm { height: 40px; padding: 0 18px; font-size: 14px; }
.lp-burger { width: 40px; height: 40px; border-radius: 50%; border: 1px solid var(--lp-line); display: grid; place-items: center; }
.lp-burger span { display: block; width: 16px; height: 2px; background: var(--lp-ink); box-shadow: 0 5px 0 var(--lp-ink), 0 -5px 0 var(--lp-ink); }

/* Hero */
.lp-hero { display: grid; grid-template-columns: 1.05fr 1fr; gap: 56px; align-items: center; padding: 56px 0 96px; }
.lp--m .lp-hero { grid-template-columns: 1fr; gap: 32px; padding: 24px 0 56px; }
.lp-hero h1 { font-size: 76px; line-height: 0.98; font-weight: 700; margin: 18px 0 24px; }
.lp--m .lp-hero h1 { font-size: 44px; }
.lp-hero h1 em { font-style: normal; color: var(--lp-ember-ink); }
.lp-lede { font-size: 19px; color: var(--lp-ink-2); max-width: 30em; }
.lp--m .lp-lede { font-size: 17px; }
.lp-cta { display: flex; gap: 12px; margin-top: 32px; flex-wrap: wrap; }
.lp-next {
  display: inline-flex; align-items: center; gap: 10px; margin-top: 28px;
  font-family: var(--font-mono); font-size: 13px; color: var(--lp-ink-2);
}
.lp-dot { width: 8px; height: 8px; border-radius: 50%; background: var(--lp-ember); box-shadow: 0 0 0 4px oklch(0.62 0.15 45 / 0.2); }

/* Photo placeholder: a drum-roaster still life drawn in CSS, labelled for the real shot. */
.lp-photo {
  position: relative; border-radius: var(--radius-xl, 20px); overflow: hidden; aspect-ratio: 4 / 5;
  background:
    radial-gradient(120% 80% at 70% 20%, oklch(0.5 0.08 50) 0%, transparent 60%),
    linear-gradient(160deg, var(--lp-roast-2), var(--lp-roast) 60%, oklch(0.22 0.03 40));
}
.lp--m .lp-photo { aspect-ratio: 4 / 3.4; }
.lp-photo--wide { aspect-ratio: 16 / 10; }
.lp-beans {
  position: absolute; inset: 0;
  background-image:
    radial-gradient(ellipse 14px 10px at 50% 50%, oklch(0.36 0.06 45) 60%, transparent 62%),
    radial-gradient(ellipse 14px 10px at 50% 50%, oklch(0.3 0.05 40) 60%, transparent 62%);
  background-size: 34px 28px, 34px 28px; background-position: 0 0, 17px 14px;
  mask-image: linear-gradient(to top, black 0%, black 30%, transparent 55%);
  opacity: 0.9;
}
.lp-photo-tag {
  position: absolute; left: 16px; bottom: 16px; padding: 6px 10px; border-radius: var(--radius-sm, 6px);
  background: oklch(0.2 0.02 40 / 0.6); color: oklch(0.92 0.02 70);
  font-family: var(--font-mono); font-size: 11px; letter-spacing: 0.04em;
}
.lp-stamp {
  position: absolute; right: 20px; top: 20px; width: 112px; height: 112px; border-radius: 50%;
  background: var(--lp-ember); color: oklch(0.2 0.03 40); display: grid; place-items: center; text-align: center;
  font-family: var(--font-display); font-weight: 700; font-size: 14px; line-height: 1.15; transform: rotate(-8deg);
}
.lp-stamp b { display: block; font-size: 30px; }

/* Sections */
.lp-section { padding: 96px 0; }
.lp--m .lp-section { padding: 64px 0; }
.lp-section--dark { background: var(--lp-roast); color: var(--lp-paper); }
.lp-section--dark .lp-eyebrow { color: var(--lp-ember); }
.lp-section--tint { background: var(--lp-paper-2); }
.lp-head { display: flex; justify-content: space-between; align-items: end; gap: 24px; margin-bottom: 40px; }
.lp--m .lp-head { flex-direction: column; align-items: start; }
.lp-head h2 { font-size: 44px; line-height: 1.05; margin-top: 12px; max-width: 16em; }
.lp--m .lp-head h2 { font-size: 32px; }

/* Roasts */
.lp-roasts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; }
.lp--m .lp-roasts { grid-template-columns: 1fr; }
.lp-bag { background: var(--lp-paper); border: 1px solid var(--lp-line); border-radius: var(--radius-lg, 14px); padding: 24px; display: flex; flex-direction: column; gap: 16px; }
.lp-bag-art { height: 150px; border-radius: var(--radius-md, 10px); position: relative; overflow: hidden; }
.lp-bag-art span {
  position: absolute; left: 14px; top: 12px; font-family: var(--font-mono); font-size: 11px;
  letter-spacing: 0.1em; text-transform: uppercase; color: oklch(0.98 0.01 70 / 0.85);
}
.lp-bag h3 { font-size: 22px; }
.lp-origin { font-size: 14px; color: var(--lp-ink-3); margin-top: 2px; }
.lp-notes { display: flex; gap: 6px; flex-wrap: wrap; }
.lp-note { font-size: 13px; padding: 4px 10px; border-radius: var(--radius-pill, 999px); background: var(--lp-paper-2); color: var(--lp-ink-2); }
.lp-roastlvl { display: flex; align-items: center; gap: 10px; font-family: var(--font-mono); font-size: 12px; color: var(--lp-ink-3); }
.lp-roastlvl i { display: block; width: 18px; height: 6px; border-radius: 3px; background: var(--lp-line); }
.lp-roastlvl i.on { background: var(--lp-roast-2); }
.lp-bag-foot { display: flex; justify-content: space-between; align-items: center; margin-top: auto; padding-top: 16px; border-top: 1px solid var(--lp-line); }
.lp-price { font-family: var(--font-display); font-weight: 700; font-size: 20px; }
.lp-price small { font-family: var(--font-body); font-weight: 400; font-size: 13px; color: var(--lp-ink-3); }

/* Process */
.lp-steps { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; }
.lp--m .lp-steps { grid-template-columns: 1fr; gap: 28px; }
.lp-step { border-top: 1px solid oklch(0.96 0.01 70 / 0.25); padding-top: 20px; }
.lp-step-n { font-family: var(--font-mono); font-size: 13px; color: var(--lp-ember); }
.lp-step h3 { font-size: 20px; margin: 10px 0 8px; }
.lp-step p { color: oklch(0.88 0.02 70); font-size: 15px; }

/* Subscription */
.lp-sub { display: grid; grid-template-columns: 1fr 1fr; gap: 56px; align-items: center; }
.lp--m .lp-sub { grid-template-columns: 1fr; gap: 32px; }
.lp-sub h2 { font-size: 44px; line-height: 1.05; margin: 12px 0 16px; }
.lp--m .lp-sub h2 { font-size: 32px; }
.lp-plans { display: grid; gap: 12px; }
.lp-plan { display: flex; justify-content: space-between; align-items: center; padding: 20px 22px; border-radius: var(--radius-lg, 14px); border: 1px solid var(--lp-line); background: var(--lp-paper); }
.lp-plan--on { border: 2px solid var(--lp-roast); }
.lp-plan b { font-family: var(--font-display); font-size: 17px; display: block; }
.lp-plan span { font-size: 14px; color: var(--lp-ink-3); }
.lp-plan .lp-price { font-size: 18px; text-align: right; }

/* Visit */
.lp-visit { display: grid; grid-template-columns: 1.2fr 1fr; gap: 56px; }
.lp--m .lp-visit { grid-template-columns: 1fr; gap: 32px; }
.lp-map {
  border-radius: var(--radius-xl, 20px); min-height: 360px; position: relative; overflow: hidden;
  background:
    linear-gradient(90deg, transparent 49.5%, var(--lp-line) 49.5%, var(--lp-line) 50.5%, transparent 50.5%) 0 0 / 120px 120px,
    linear-gradient(0deg, transparent 49.5%, var(--lp-line) 49.5%, var(--lp-line) 50.5%, transparent 50.5%) 0 0 / 120px 120px,
    var(--lp-paper-2);
}
.lp--m .lp-map { min-height: 240px; }
.lp-map-road { position: absolute; left: -10%; right: -10%; top: 58%; height: 14px; background: var(--lp-paper); transform: rotate(-12deg); }
.lp-pin { position: absolute; left: 52%; top: 44%; width: 22px; height: 22px; border-radius: 50% 50% 50% 0; background: var(--lp-ember); transform: rotate(-45deg); box-shadow: 0 6px 16px oklch(0.3 0.05 40 / 0.35); }
.lp-map-label { position: absolute; left: calc(52% + 26px); top: calc(44% - 4px); font-family: var(--font-mono); font-size: 12px; background: var(--lp-paper); padding: 4px 8px; border-radius: var(--radius-sm, 6px); }
.lp-visit h2 { font-size: 40px; line-height: 1.05; margin: 12px 0 24px; }
.lp--m .lp-visit h2 { font-size: 30px; }
.lp-hours { width: 100%; border-collapse: collapse; font-size: 15px; margin: 8px 0 28px; }
.lp-hours td { padding: 10px 0; border-bottom: 1px solid var(--lp-line); }
.lp-hours td:last-child { text-align: right; font-family: var(--font-mono); font-size: 14px; }
.lp-hours tr.today td { font-weight: 600; }
.lp-address { font-size: 17px; margin-bottom: 4px; }

/* Footer */
.lp-foot { background: oklch(0.2 0.025 40); color: oklch(0.8 0.02 70); padding: 56px 0 40px; font-size: 14px; }
.lp-foot-grid { display: grid; grid-template-columns: 2fr 1fr 1fr 1fr; gap: 32px; }
.lp--m .lp-foot-grid { grid-template-columns: 1fr 1fr; }
.lp-foot h4 { margin: 0 0 12px; font-family: var(--font-mono); font-size: 12px; letter-spacing: 0.1em; text-transform: uppercase; color: oklch(0.65 0.03 60); font-weight: 500; }
.lp-foot ul { list-style: none; padding: 0; margin: 0; display: grid; gap: 8px; }
.lp-foot .lp-logo { color: var(--lp-paper); margin-bottom: 12px; }
.lp-foot .lp-logo-mark { background: var(--lp-ember); }
.lp-foot .lp-logo-mark::after { background: oklch(0.2 0.025 40); }
.lp-foot-bottom { margin-top: 48px; padding-top: 20px; border-top: 1px solid oklch(0.35 0.02 40); display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; font-size: 13px; }

